-- Festa Munich: Catalog categories and product seed
-- Safe to run repeatedly. It does not drop or delete existing data.

-- Categories
UPDATE public.categories
SET is_active = false, updated_at = now()
WHERE name IN ('Leather Jackets', 'Textile Outerwear', 'Tailoring & Blazers', 'Accessories & Bags');

INSERT INTO public.categories (name, slug, description, image_url, icon_name, is_active, display_order)
VALUES
  ('Lederhosen', 'lederhosen', 'Traditional Bavarian leather garments and short lederhosen.', 'https://images.unsplash.com/photo-1521572163474-6864f9cf17ab?auto=format&fit=crop&w=1200&q=85', 'shirt', true, 1),
  ('Traditional Shirts', 'traditional-shirts', 'Classic checked and embroidered shirts for Oktoberfest and celebrations.', 'https://images.unsplash.com/photo-1602810318383-e386cc2a3ccf?auto=format&fit=crop&w=1200&q=85', 'shirt', true, 2),
  ('Footwear', 'footwear', 'Handcrafted traditional shoes and comfortable Bavarian footwear.', 'https://images.unsplash.com/photo-1542291026-7eec264c27ff?auto=format&fit=crop&w=1200&q=85', 'shoe', true, 3),
  ('Socks', 'socks', 'Wool and cotton traditional socks with Bavarian patterns.', 'https://images.unsplash.com/photo-1582966772680-860e372bb558?auto=format&fit=crop&w=1200&q=85', 'layers', true, 4),
  ('Accessories', 'accessories', 'Belts, hats, suspenders and finishing details for your look.', 'https://images.unsplash.com/photo-1553062407-98eeb64c6a62?auto=format&fit=crop&w=1200&q=85', 'briefcase', true, 5),
  ('Ladies Collection', 'ladies-collection', 'Elegant Bavarian-inspired garments for women.', 'https://images.unsplash.com/photo-1496747611176-843222e1e57c?auto=format&fit=crop&w=1200&q=85', 'heart', true, 6),
  ('Gifts', 'gifts', 'Giftable pieces for weddings, festivals and special occasions.', 'https://images.unsplash.com/photo-1549465220-1a8b9238cd48?auto=format&fit=crop&w=1200&q=85', 'gift', true, 7),
  ('New Arrivals', 'new-arrivals', 'The newest additions to the Festa Munich collection.', 'https://images.unsplash.com/photo-1445205170230-053b83016050?auto=format&fit=crop&w=1200&q=85', 'sparkles', true, 8)
ON CONFLICT (name) DO UPDATE SET
  slug = EXCLUDED.slug,
  description = EXCLUDED.description,
  image_url = EXCLUDED.image_url,
  icon_name = EXCLUDED.icon_name,
  is_active = EXCLUDED.is_active,
  display_order = EXCLUDED.display_order,
  updated_at = now();

-- Subcategories
INSERT INTO public.subcategories (category_id, name, slug, description, display_order)
SELECT c.id, s.name, s.slug, s.description, s.display_order
FROM public.categories c
JOIN (VALUES
  ('Lederhosen', 'Classic Lederhosen', 'classic-lederhosen', 'Traditional short leather styles.', 1),
  ('Lederhosen', 'Embroidered Lederhosen', 'embroidered-lederhosen', 'Detailed embroidery and premium finishes.', 2),
  ('Footwear', 'Haferlschuhe', 'haferlschuhe', 'Traditional Bavarian shoes.', 1),
  ('Footwear', 'Casual Shoes', 'casual-shoes', 'Everyday shoes with traditional details.', 2),
  ('Accessories', 'Belts and Suspenders', 'belts-suspenders', 'Belts, braces and leather details.', 1),
  ('Accessories', 'Hats', 'hats', 'Traditional felt and wool hats.', 2),
  ('Ladies Collection', 'Dirndl', 'dirndl', 'Classic and modern dirndl styles.', 1),
  ('Ladies Collection', 'Blouses', 'blouses', 'Traditional ladies blouses.', 2),
  ('Socks', 'Wool Socks', 'wool-socks', 'Warm traditional wool socks.', 1),
  ('Socks', 'Knee High Socks', 'knee-high-socks', 'Classic knee-high styles.', 2)
) AS s(category_name, name, slug, description, display_order)
ON c.name = s.category_name
ON CONFLICT (category_id, name) DO UPDATE SET
  slug = EXCLUDED.slug,
  description = EXCLUDED.description,
  display_order = EXCLUDED.display_order,
  updated_at = now();

-- Products
