  ('Alpine Classic Lederhosen', 'Stone grey suede short lederhosen', 'Lederhosen', 189.00, 229.00, ARRAY['https://images.unsplash.com/photo-1551488831-00ddcb6c6bd3?auto=format&fit=crop&w=1200&q=85'], 'A versatile stone grey leather short designed for festivals, weddings and everyday Bavarian style.', ARRAY['Soft suede finish', 'Antique metal details', 'Adjustable waist tabs'], 'Premium suede leather', ARRAY['46','48','50','52','54','56'], ARRAY['Stone Grey'], 24, 5, true, true, true, 'BESTSELLER', 'FM-LH-001', ARRAY['Spot clean only', 'Air dry naturally'], 'Designed for long-term wear with repairable construction.', 'Alpine Classic Lederhosen | Festa Munich', 'Stone grey premium suede lederhosen with traditional details.'),
  ('Midnight Embroidered Lederhosen', 'Black leather with cream embroidery', 'Lederhosen', 239.00, 279.00, ARRAY['https://images.unsplash.com/photo-1551488831-00ddcb6c6bd3?auto=format&fit=crop&w=1200&q=85'], 'A striking black lederhosen with cream embroidery for a refined evening festival look.', ARRAY['Hand-finished embroidery', 'Reinforced seams', 'Adjustable suspenders'], 'Velvet-finish leather', ARRAY['46','48','50','52','54','56'], ARRAY['Black'], 18, 4, true, true, true, 'SIGNATURE', 'FM-LH-002', ARRAY['Professional leather clean', 'Store away from moisture'], 'Made with durable materials selected for repeated seasonal wear.', 'Midnight Embroidered Lederhosen | Festa Munich', 'Black embroidered leather lederhosen for formal Bavarian occasions.'),
  ('Cognac Heritage Lederhosen', 'Warm cognac leather with classic stitching', 'Lederhosen', 219.00, 259.00, ARRAY['https://images.unsplash.com/photo-1596755389378-c31d21fd1273?auto=format&fit=crop&w=1200&q=85'], 'Warm cognac leather and traditional stitching create a timeless heritage silhouette.', ARRAY['Natural leather patina', 'Classic front flap', 'Brass-tone buttons'], 'Full-grain leather', ARRAY['46','48','50','52','54','56'], ARRAY['Cognac'], 20, 5, true, false, true, 'HERITAGE', 'FM-LH-003', ARRAY['Use leather conditioner', 'Keep in a breathable garment bag'], 'Full-grain leather ages beautifully and reduces replacement cycles.', 'Cognac Heritage Lederhosen | Festa Munich', 'Cognac full-grain leather lederhosen with heritage Bavarian styling.'),
  ('Forest Green Festival Shorts', 'Modern green suede lederhosen', 'Lederhosen', 199.00, 239.00, ARRAY['https://images.unsplash.com/photo-1515886657613-9f3515b0c78f?auto=format&fit=crop&w=1200&q=85'], 'A modern forest green interpretation of the classic Bavarian short.', ARRAY['Soft brushed suede', 'Contrast piping', 'Comfort stretch lining'], 'Suede leather blend', ARRAY['46','48','50','52','54'], ARRAY['Forest Green'], 15, 4, false, true, true, 'NEW', 'FM-LH-004', ARRAY['Spot clean', 'Do not machine wash'], 'Low-impact dyes and a lining made with recycled fibres.', 'Forest Green Festival Lederhosen | Festa Munich', 'Modern forest green suede festival shorts with traditional tailoring.'),
  ('Black Embroidered Trachten Shorts', 'Detailed dark Bavarian leather shorts', 'Lederhosen', 229.00, 269.00, ARRAY['https://images.unsplash.com/photo-1558618666-fcd25c85cd64?auto=format&fit=crop&w=1200&q=85'], 'Dark leather shorts decorated with ornate embroidery and polished hardware.', ARRAY['Decorative floral embroidery', 'Hidden phone pocket', 'Removable braces'], 'Soft napa leather', ARRAY['46','48','50','52','54','56'], ARRAY['Black'], 13, 4, false, true, true, 'LIMITED', 'FM-LH-005', ARRAY['Leather specialist clean only'], 'Built in small batches to reduce excess inventory.', 'Black Embroidered Trachten Shorts | Festa Munich', 'Limited black Bavarian leather shorts with ornate embroidery.'),
