  ('Charcoal Ribbed Knee Socks', 'Deep charcoal traditional socks', 'Socks', 24.00, 32.00, ARRAY['https://images.unsplash.com/photo-1586350977771-b3b0abd50c82?auto=format&fit=crop&w=1200&q=85'], 'A versatile charcoal sock with subtle ribbing and a supportive knee-high fit.', ARRAY['Subtle rib knit', 'Reinforced sole', 'Soft stretch finish'], 'Merino wool blend', ARRAY['39-42','43-46'], ARRAY['Charcoal'], 48, 10, false, false, true, 'ESSENTIAL', 'FM-SK-002', ARRAY['Machine wash cold', 'Dry flat'], 'Merino blend selected for warmth and durability.', 'Charcoal Ribbed Knee Socks | Festa Munich', 'Charcoal merino-blend knee-high socks with a comfortable fit.'),
  ('Cognac Leather Belt', 'Classic engraved leather belt', 'Accessories', 49.00, 69.00, ARRAY['https://images.unsplash.com/photo-1553062407-98eeb64c6a62?auto=format&fit=crop&w=1200&q=85'], 'A sturdy cognac belt with a traditional buckle and subtle engraved detailing.', ARRAY['Solid metal buckle', 'Five-hole adjustment', 'Edge-painted finish'], 'Full-grain leather', ARRAY['80','90','100','110','120'], ARRAY['Cognac'], 32, 7, true, false, true, 'CRAFTED', 'FM-AC-001', ARRAY['Wipe with a dry cloth', 'Condition twice yearly'], 'Full-grain leather is selected for longevity and repairability.', 'Cognac Leather Belt | Festa Munich', 'Traditional cognac full-grain leather belt with engraved details.'),
  ('Felt Alpine Hat', 'Classic green felt festival hat', 'Accessories', 54.00, 74.00, ARRAY['https://images.unsplash.com/photo-1521369909029-2afed882baee?auto=format&fit=crop&w=1200&q=85'], 'A structured felt hat finished with a simple band for an unmistakable Alpine look.', ARRAY['Structured crown', 'Soft sweatband', 'Adjustable inner band'], 'Wool felt', ARRAY['S','M','L','XL'], ARRAY['Forest Green'], 25, 5, false, true, true, 'NEW', 'FM-AC-002', ARRAY['Spot clean only', 'Store on a hat stand'], 'Wool felt is naturally resilient and designed for many seasons.', 'Felt Alpine Hat | Festa Munich', 'Forest green wool felt Alpine hat with an adjustable inner band.'),
  ('Leather Suspender Set', 'Adjustable braces with antique clips', 'Accessories', 44.00, 59.00, ARRAY['https://images.unsplash.com/photo-1529139574466-a303027c1d8b?auto=format&fit=crop&w=1200&q=85'], 'Adjustable leather suspenders that complete a traditional lederhosen outfit.', ARRAY['Antique-finish clips', 'Adjustable length', 'Reinforced leather tabs'], 'Leather and elastic', ARRAY['One Size'], ARRAY['Brown'], 34, 8, true, false, false, 'ESSENTIAL', 'FM-AC-003', ARRAY['Wipe leather tabs clean', 'Store flat'], 'Replaceable clips and repairable leather tabs reduce waste.', 'Leather Suspender Set | Festa Munich', 'Adjustable brown leather suspenders with antique-finish clips.'),
  ('Midnight Velvet Dirndl', 'Elegant dark dirndl dress', 'Ladies Collection', 179.00, 219.00, ARRAY['https://images.unsplash.com/photo-1496747611176-843222e1e57c?auto=format&fit=crop&w=1200&q=85'], 'A modern midnight dirndl with velvet texture and a flattering fitted bodice.', ARRAY['Fitted bodice', 'Full gathered skirt', 'Adjustable apron ties'], 'Cotton velvet and linen', ARRAY['32','34','36','38','40','42'], ARRAY['Midnight'], 16, 4, true, true, true, 'SIGNATURE', 'FM-LD-001', ARRAY['Dry clean recommended'], 'Made in small batches with durable natural-fibre panels.', 'Midnight Velvet Dirndl | Festa Munich', 'Elegant midnight velvet dirndl with a fitted bodice.'),
  ('Rose Alpine Dirndl', 'Soft rose dirndl with linen apron', 'Ladies Collection', 169.00, 209.00, ARRAY['https://images.unsplash.com/photo-1483985988355-763728e1935b?auto=format&fit=crop&w=1200&q=85'], 'A soft rose dirndl balanced with a natural linen apron and clean modern lines.', ARRAY['Linen apron', 'Hidden side zip', 'Adjustable bodice lacing'], 'Cotton and linen', ARRAY['32','34','36','38','40','42'], ARRAY['Rose'], 18, 4, false, true, true, 'NEW', 'FM-LD-002', ARRAY['Machine wash gentle', 'Air dry'], 'Natural fibres and long-lasting construction for repeat events.', 'Rose Alpine Dirndl | Festa Munich', 'Modern rose cotton and linen dirndl with a natural apron.'),
