  ('Munich Leather Key Fob', 'Small engraved leather accessory', 'Gifts', 19.00, 29.00, ARRAY['https://images.unsplash.com/photo-1553062407-98eeb64c6a62?auto=format&fit=crop&w=1200&q=85'], 'A compact leather key fob with a brass ring and traditional engraved detail.', ARRAY['Brass key ring', 'Edge-finished leather', 'Gift pouch included'], 'Full-grain leather', ARRAY['One Size'], ARRAY['Cognac'], 75, 15, false, true, false, 'SMALL GIFT', 'FM-GF-002', ARRAY['Wipe with a dry cloth'], 'A small durable accessory designed to avoid disposable gift items.', 'Munich Leather Key Fob | Festa Munich', 'Engraved cognac leather key fob with brass ring.'),
  ('Alpine Weekend Bundle', 'Lederhosen essentials collection', 'New Arrivals', 249.00, 299.00, ARRAY['https://images.unsplash.com/photo-1445205170230-053b83016050?auto=format&fit=crop&w=1200&q=85'], 'A complete starter bundle pairing classic lederhosen styling with shirt, socks and suspenders.', ARRAY['Curated outfit bundle', 'Seasonal color coordination', 'Gift-ready presentation'], 'Leather, cotton and wool', ARRAY['46','48','50','52','54','56'], ARRAY['Cognac'], 12, 3, true, true, true, 'BUNDLE', 'FM-NA-001', ARRAY['Follow individual care labels'], 'Bundled pieces are selected for durable, repeat seasonal use.', 'Alpine Weekend Bundle | Festa Munich', 'Complete Bavarian outfit bundle with lederhosen essentials.'),
  ('Embroidered Pocket Lederhosen', 'Olive suede with floral detailing', 'Lederhosen', 209.00, 249.00, ARRAY['https://images.unsplash.com/photo-1515886657613-9f3515b0c78f?auto=format&fit=crop&w=1200&q=85'], 'Olive suede lederhosen with decorative pocket embroidery and antique buttons.', ARRAY['Floral pocket embroidery', 'Adjustable waist', 'Soft inner lining'], 'Suede leather', ARRAY['46','48','50','52','54'], ARRAY['Olive'], 17, 4, false, true, true, 'NEW', 'FM-LH-006', ARRAY['Spot clean only', 'Avoid prolonged rain'], 'Small-batch production helps reduce unused material.', 'Embroidered Pocket Lederhosen | Festa Munich', 'Olive suede lederhosen with floral pocket embroidery.'),
