  ('Classic White Trachten Shirt', 'Clean cotton shirt with stand collar', 'Traditional Shirts', 64.00, 84.00, ARRAY['https://images.unsplash.com/photo-1598033129183-c4f50c736f10?auto=format&fit=crop&w=1200&q=85'], 'A clean white shirt with a traditional stand collar and comfortable regular fit.', ARRAY['Stand collar', 'Reinforced cuffs', 'Natural buttons'], 'Cotton poplin', ARRAY['S','M','L','XL','XXL'], ARRAY['White'], 33, 7, false, false, true, 'CLASSIC', 'FM-SH-006', ARRAY['Machine wash cold', 'Iron medium'], 'Long-lasting poplin helps reduce frequent replacement.', 'Classic White Trachten Shirt | Festa Munich', 'Classic white cotton Trachten shirt with a stand collar.')
